@kv2019i  I'm seeing a degradation in cavs timer that I'm not seeing in other implementations. I've a simple sample that just configure a timeout for every 1s and try to take a semaphore that will be given in the timeout callback. When the semaphore is taken the thread just busy/wait for 90% of the tick time.
Basically, with lower `CONFIG_SYS_CLOCK_TICKS_PER_SEC` the timer is constantly triggered, but with higher values the timer gets degraded over time.

There were no additional ticks  interruptions though.

So, I tried to come up with something similar to SoF scheduler but simpler. I run this sample in cavs25 with two different configurations, `CONFIG_SYS_CLOCK_TICKS_PER_SEC=80000` and `CONFIG_SYS_CLOCK_TICKS_PER_SEC=12000`. With 80k we missed some ticks and with 10k we have two cpus handling the "same" tick. Please see the logs below:

80k
![bug-80k](https://user-images.githubusercontent.com/882919/181111081-20b492f3-e281-4731-8d20-bfb072618b46.png)

12k
![bug-12k](https://user-images.githubusercontent.com/882919/181111175-bf5e0833-ab88-4cfa-8c9e-a1c8961c66a6.png)

The code used to test it was:
```
#include <zephyr/zephyr.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(sample, LOG_LEVEL_INF);


#define STACK_SIZE 2048
#define TIMER_PERIOD_US 1000

K_THREAD_STACK_ARRAY_DEFINE(work_stacks, CONFIG_MP_NUM_CPUS, STACK_SIZE);


struct zephyr_domain {
	struct k_thread domain_thread[CONFIG_MP_NUM_CPUS];
	struct k_sem sem[CONFIG_MP_NUM_CPUS];
};

struct k_timer timer;
static struct zephyr_domain zd = {};

void work_fn(void *arg1, void *arg2, void *arg3)
{
	int cpu = (int)arg1;
	struct zephyr_domain *zephyr_domain = arg2;

	while (true) {
		k_sem_take(&zephyr_domain->sem[cpu], K_FOREVER);

		/* Lets spinning to simulate some work */
		k_busy_wait(TIMER_PERIOD_US * 0.7);
	}
}

static void timer_fn(struct k_timer *t)
{
	int core;

	struct zephyr_domain *zephyr_domain = k_timer_user_data_get(t);

	if (!zephyr_domain) {
		return;
	}

	for (core = 0; core < CONFIG_MP_NUM_CPUS; core++) {
		k_sem_give(&zephyr_domain->sem[core]);
	}

	LOG_INF("CPU[%d] uptime: %llu\n", arch_curr_cpu()->id, k_uptime_get());
}

void main(void)
{
	k_timeout_t start = {0};
	k_timeout_t timeout = K_USEC(TIMER_PERIOD_US);

	k_timer_init(&timer, timer_fn, NULL);
	k_timer_user_data_set(&timer, &zd);

	LOG_INF("number of ticks per second: %u\n", CONFIG_SYS_CLOCK_TICKS_PER_SEC);
	for (int i = 0; i < CONFIG_MP_NUM_CPUS; i++) {

		k_sem_init(&zd.sem[i], 0, 999);
		k_thread_create(&zd.domain_thread[i], work_stacks[i], STACK_SIZE,
				work_fn, (void *)i, &zd, NULL,
				-CONFIG_NUM_COOP_PRIORITIES, 0, K_FOREVER);
		k_thread_cpu_mask_clear(&zd.domain_thread[i]);
		k_thread_cpu_mask_enable(&zd.domain_thread[i], i);

		k_thread_start(&zd.domain_thread[i]);
	}
	k_timer_start(&timer, start, timeout);
}
```
